// The two lines under the prompt. Line 1 rides at the end of Claude Code's own
// hint line and says how full things are: context, and how much of each usage
// window is gone. Line 2 sits directly under it, in colour: the model and its
// effort, then what happens next: when the prompt cache goes cold, when each
// window resets or runs out, what is running, what compacts.
//
// Pure, like core.ts: the mod hands in what it knows, the tests call it.

import { SEP, clock, duration, fit, num, pace, pct, roundEta, str, tokens } from './core'
import type { Options, Payload, Placed, Segment, Tone } from './core'

/** Added to a segment's priority while it warns, as core's segments do. */
const URGENT = 50

function urgent(segment: Segment): Segment {
  return segment.tone === 'warn' || segment.tone === 'bad' ? { ...segment, priority: segment.priority + URGENT } : segment
}

function pressure(percent: number): Tone | undefined {
  if (percent >= 95) return 'bad'
  if (percent >= 80) return 'warn'
  return undefined
}

const WINDOW_NAME = { five_hour: '5h', seven_day: 'wk' } as const

// ------------------------------------------------------------------ line 1

/** `Opus 5.5 xhigh`: the effort stays even in the narrowest form. */
export function modelNext(p: Payload): Segment | undefined {
  const name = str(p.model?.display_name) ?? str(p.model?.id)
  if (!name) return undefined
  const level = str(p.effort?.level, 12)
  const fast = p.fast_mode === true ? ' fast' : ''
  const family = name.split(' ')[0] ?? name
  const forms = level
    ? [`${name} ${level}${fast}`, `${family} ${level}${fast}`, `${family} ${level}`]
    : [`${name}${fast}`, family]
  return { key: 'model', priority: 95, tone: 'accent', forms }
}

export function contextNow(p: Payload): Segment | undefined {
  const w = p.context_window
  const used = num(w?.used_percentage)
  if (used === undefined || used < 0) return undefined
  // The window's headroom isn't the room before auto-compact, so the line
  // shows the percentage alone; the `/g-line` pane says the rest.
  return { key: 'context', priority: 90, tone: pressure(used), forms: [`ctx ${pct(used)}`] }
}

/** `5h 64%`, with `!` once the window is on pace to run out (the line is drawn dim). */
export function windowNow(p: Payload, kind: 'five_hour' | 'seven_day', now: number): Segment | undefined {
  const window = p.rate_limits?.[kind]
  const used = num(window?.used_percentage)
  if (used === undefined || used < 0) return undefined
  const state = pace(kind, window, now)
  const name = WINDOW_NAME[kind]
  const priority = kind === 'five_hour' ? 85 : 70
  if (state?.kind === 'full') return { key: kind, priority, tone: 'bad', forms: [`${name} full`] }
  if (state?.kind === 'hot') return { key: kind, priority, tone: 'warn', forms: [`${name} ${pct(used)}!`] }
  return { key: kind, priority, tone: pressure(used), forms: [`${name} ${pct(used)}`] }
}

export function spendNow(p: Payload): Segment | undefined {
  const used = num(p.rate_limits?.spend_limit?.used_percentage)
  if (used === undefined || used < 0) return undefined
  return { key: 'spend', priority: 75, tone: pressure(used), forms: [`spend ${pct(used)}`] }
}

/** Line 1's segments, in order. */
export function lineNow(p: Payload, o: Options): Segment[] {
  return [contextNow(p), windowNow(p, 'five_hour', o.now), windowNow(p, 'seven_day', o.now), spendNow(p)]
    .filter((s): s is Segment => s !== undefined).map(urgent)
}

// ------------------------------------------------------------------ line 2

/**
 * `cache 58m`, green while warm, amber in its last minutes, then `cache cold`;
 * after a compaction, the summary the next turn writes instead.
 */
export function cacheNext(p: Payload, now: number): Segment | undefined {
  const cache = p.prompt_cache
  if (!cache || cache.caching_observed !== true) return undefined
  const expires = num(cache.expires_at)
  if (cache.compacted === true) {
    const size = num(cache.recache_tokens_if_cold)
    return { key: 'cache', priority: 90,
      forms: size && size > 0 ? [`compacted, next turn caches ${tokens(size)}`, 'cache compacted'] : ['cache compacted'] }
  }
  if (cache.warm === true && expires !== undefined && expires > now) {
    const left = expires - now
    const soon = left <= (cache.ttl === '1h' ? 300 : 60)
    // `~`: the mod knows when the last request ran and the cache's lifetime,
    // not the provider's own expiry.
    const about = left < 60 ? '<1m' : `~${duration(left, true)}`
    return { key: 'cache', priority: 90, tone: soon ? 'warn' : 'ok',
      forms: [`cache warm ${left < 60 ? '<1m' : `~${duration(left)}`}`, `cache ${about}`] }
  }
  const recache = num(cache.recache_tokens_if_cold)
  return { key: 'cache', priority: 90, tone: 'warn',
    forms: recache && recache > 0 ? [`cache cold, next turn rebuilds ${tokens(recache)}`, 'cache cold'] : ['cache cold'] }
}

/** When a window resets, or (on pace to run out) roughly when it runs out. */
export function windowNext(p: Payload, kind: 'five_hour' | 'seven_day', o: Options): Segment | undefined {
  const window = p.rate_limits?.[kind]
  const used = num(window?.used_percentage)
  const resets = num(window?.resets_at)
  if (used === undefined || used < 0 || resets === undefined || resets <= o.now) return undefined
  const name = WINDOW_NAME[kind]
  const state = pace(kind, window, o.now)
  const at = (t: number) => clock(t, o.now, o.utcOffsetMinutes)
  const left = resets - o.now
  // A healthy window's reset is the first thing to go when room is short.
  const priority = kind === 'five_hour' ? 40 : 35
  if (state?.kind === 'full') {
    return { key: `${kind}_next`, priority, tone: 'bad', forms: [`${name} back in ${duration(left)}`, `${name} back ${duration(left, true)}`] }
  }
  if (state?.kind === 'hot') {
    const tone: Tone = state.eta - o.now < 30 * 60 ? 'bad' : 'warn'
    return { key: `${kind}_next`, priority, tone,
      forms: [`${name} out ~${at(roundEta(state.eta, o.now))}, resets ${at(resets)}`, `${name} out ~${at(roundEta(state.eta, o.now))}`] }
  }
  return { key: `${kind}_next`, priority, forms: [`${name} resets in ${duration(left)}`, `${name} resets ${duration(left, true)}`] }
}

export function spendNext(p: Payload): Segment | undefined {
  const spend = p.rate_limits?.spend_limit
  const usd = num(spend?.used_usd)
  const cap = num(spend?.limit_usd)
  if (usd === undefined || !cap) return undefined
  const period = ['daily', 'weekly', 'monthly'].includes(spend?.period ?? '') ? ` ${spend?.period}` : ''
  return { key: 'spend_next', priority: 75, forms: [`$${Math.round(usd)} of $${Math.round(cap)}${period}`, `$${Math.round(usd)}/$${Math.round(cap)}`] }
}

/** Line 2's segments: the model and effort, the cache, the windows' timing, then what the mod adds (agents, compaction, today, branch, account). */
export function lineNext(p: Payload, o: Options, extras: Segment[] = []): Segment[] {
  return [modelNext(p), cacheNext(p, o.now), windowNext(p, 'five_hour', o), windowNext(p, 'seven_day', o), spendNext(p), ...extras]
    .filter((s): s is Segment => s !== undefined).map(urgent)
}

// ---------------------------------------------------------------- the deck

/** Columns line 2 has: it starts at the row's two-column indent, and the engine keeps three columns free at its end. */
export function nextRoom(columns: number | undefined): number | undefined {
  return columns === undefined ? undefined : columns - 5
}

export type Deck = { now: Placed[]; next: Placed[] }

/**
 * Both lines, each fitted to its own room. What line 1 has no room for moves
 * down to line 2 instead of vanishing; line 2 drops its least important
 * segments only when both lines are full.
 */
export function deck(p: Payload, o: Options, rooms: { now?: number; next?: number }, extras: Segment[] = []): Deck {
  const now = lineNow(p, o)
  const placed = rooms.now !== undefined && rooms.now < 4 ? [] : fit(now, rooms.now)
  const kept = new Set(placed.map(part => part.key))
  const moved = now.filter(segment => !kept.has(segment.key))
  const next = [...lineNext(p, o, extras), ...moved]
  return { now: placed, next: rooms.next !== undefined && rooms.next < 4 ? [] : fit(next, rooms.next) }
}

files.hooks/glance.ts:
// What Claude reads when it calls g-line's `status` tool, which is off unless
// turned on (`claude_reads: true`): a small JSON snapshot of the session's
// reported context, the account's usage windows and the estimated prompt-cache
// expiry. Observations only, with their scope and basis; never advice.
//
// Pure, like core.ts; the mod hands in the figures, the tests call it.

import { num, pace, roundEta } from './core'
import type { Payload } from './core'

export const STATUS_TOOL = 'status'

export const STATUS_DESCRIPTION = [
  "Read this Claude Code session's reported context use and automatic-compaction headroom, the account's usage windows,",
  'and the estimated prompt-cache expiry, as g-line observed them.',
  'Use when the user asks about these figures or explicitly requests a capacity check.',
  'This tool observes state; it changes no settings. Estimates may be stale and are not task budgets.',
  'Do not poll, send keep-alive prompts, reduce requested work, or change model, effort or compaction settings',
  'based on this result without the user\'s authorization.',
].join(' ')

export const STATUS_SCHEMA = {
  type: 'object',
  properties: { section: { type: 'string', enum: ['all', 'context', 'limits', 'cache'], description: 'Which part to read; all by default.' } },
}

export type StatusInput = {
  p: Payload
  /** Unix seconds now, and when the figures were last observed. */
  now: number
  observedAt?: number
  /** Tokens at which auto-compact runs, when it is on; undefined when off or unknown. */
  compactAt?: number
  compactOn?: boolean
  section?: string
  disabled?: boolean
}

const iso = (seconds: number | undefined) => (seconds === undefined ? null : new Date(Math.floor(seconds) * 1000).toISOString())

function window(p: Payload, kind: 'five_hour' | 'seven_day', now: number) {
  const w = p.rate_limits?.[kind]
  const used = num(w?.used_percentage)
  if (used === undefined) return null
  const state = pace(kind, w, now)
  return {
    used_percent: Math.round(used),
    resets_at: iso(num(w?.resets_at)),
    projected_limit_at: state?.kind === 'hot' ? iso(roundEta(state.eta, now)) : state?.kind === 'full' ? 'reached' : null,
  }
}

/** The snapshot as a JSON string. Unknown stays null; nothing is guessed. */
export function statusJson(s: StatusInput): string {
  if (s.disabled) return JSON.stringify({ schema: 1, state: 'disabled', note: 'g-line is turned off in this session (/g-line on turns it back on).' })
  const section = ['context', 'limits', 'cache'].includes(s.section ?? '') ? s.section : 'all'
  const out: Record<string, unknown> = { schema: 1, captured_at: iso(s.now), observed_at: iso(s.observedAt) }
  if (section === 'all' || section === 'context') {
    const w = s.p.context_window
    const used = num(w?.total_input_tokens)
    out.context = {
      scope: 'main_session',
      used_tokens: used ?? null,
      window_tokens: num(w?.context_window_size) ?? null,
      used_percent: num(w?.used_percentage) === undefined ? null : Math.round(num(w?.used_percentage) ?? 0),
      auto_compact: s.compactOn === false
        ? { enabled: false }
        : { enabled: s.compactAt !== undefined ? true : null, threshold_tokens: s.compactAt ?? null,
            headroom_tokens: s.compactAt !== undefined && used !== undefined ? Math.max(0, s.compactAt - used) : null,
            basis: 'engine_local_estimate' },
    }
  }
  if (section === 'all' || section === 'limits') {
    out.limits = {
      scope: 'account',
      five_hour: window(s.p, 'five_hour', s.now),
      seven_day: window(s.p, 'seven_day', s.now),
      projection_basis: 'rounded_linear_since_window_start',
    }
  }
  if (section === 'all' || section === 'cache') {
    const c = s.p.prompt_cache
    const expires = num(c?.expires_at)
    out.cache = c?.caching_observed
      ? { scope: 'main_session_last_request',
          state: c.compacted ? 'compacted' : c.warm && expires !== undefined && expires > s.now ? 'estimated_warm' : 'estimated_cold',
          estimated_expires_at: iso(expires), lifetime: c.ttl ?? null, rebuild_tokens_if_cold: num(c.recache_tokens_if_cold) ?? null,
          basis: 'configured_ttl_and_observed_request' }
      : null
  }
  return JSON.stringify(out)
}

files.hooks/pulse.ts:
// Pulse: a few AI-dev headlines from g-line's own static feed, for the time a
// long turn keeps you waiting. Off unless turned on (`/g-line pulse`). When
// on, the mod fetches one static JSON file now and then; it sends nothing
// about you, and it never fetches while drawing.
//
// Pure: parsing and cleaning the feed. Feed text is untrusted, so every
// string is stripped of escapes and control characters and cut to length
// before it can reach the terminal.

import type { PulseFeed, PulseItem } from '../types'

export type { PulseFeed, PulseItem }

export const PULSE_URL = 'https://raw.githubusercontent.com/lifeofgurpreet/g-line/pulse/pulse.json'
/** How long a fetched feed is used before the next fetch. */
export const PULSE_TTL_MS = 45 * 60_000
/** How long a turn runs before the spinner starts showing headlines. */
export const PULSE_AFTER_MS = 15_000
/** How long each headline stays on the spinner and on Pulse's row. */
export const PULSE_EVERY_MS = 8_000

/** Pulse's 8-second beats per headline at each speed; paused never moves on. */
export const PULSE_BEATS = { normal: 1, slow: 5, paused: 0 } as const

/** Whether `mute` names the item's source: a case-insensitive match within it. */
export function muted(item: PulseItem, mute: readonly string[]): boolean {
  const source = item.source.toLowerCase()
  return mute.some(word => source.includes(word.toLowerCase()))
}
/** The longest text the reader shows for one item. */
export const TEXT_MAX = 600
/** How many items the reader shows at once. */
export const READER_PAGE = 5

// CSI and OSC escape sequences, then any C0/C1 control, then bidi and zero-width controls.
const ESCAPES = /\u001b\[[0-?]*[ -/]*[@-~]|\u001b\][^\u0007\u001b]*(?:\u0007|\u001b\\)|\u001b[@-_]/g
const CONTROLS = /[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2060-\u2069\ufeff]/g
// Variation selectors are dropped, so a symbol draws in its one-column text form.
const SELECTORS = /[\ufe00-\ufe0f]/g
// Feed text, unlike the mod's own, can hold emoji and East Asian wide characters (two columns) and combining marks (none).
const WIDE = /\p{Emoji_Presentation}|[\u1100-\u115f\u2e80-\u303e\u3041-\ua4cf\uac00-\ud7a3\uf900-\ufaff\ufe30-\ufe4f\uff00-\uff60\uffe0-\uffe6\u{20000}-\u{3fffd}]/u
const ZERO = /[\p{Mn}\p{Me}]/u

const cell = (ch: string) => ZERO.test(ch) ? 0 : WIDE.test(ch) ? 2 : 1

/** Display columns of feed text. */
export function cells(text: string): number {
  let n = 0
  for (const ch of text) n += cell(ch)
  return n
}

/** Text safe to draw: no escapes or control characters, one line, at most `max` columns. */
export function clean(value: unknown, max: number): string {
  if (typeof value !== 'string') return ''
  const text = value.replace(ESCAPES, '').replace(CONTROLS, ' ').replace(SELECTORS, '').replace(/\s+/g, ' ').trim()
  if (cells(text) <= max) return text
  let kept = ''
  let used = 0
  for (const ch of text) {
    used += cell(ch)
    if (used > max - 1) break
    kept += ch
  }
  return `${kept.trimEnd()}…`
}

/** Only plain https links, short enough to be a link and not a payload. */
export function safeUrl(value: unknown): string | undefined {
  if (typeof value !== 'string' || value.length > 400) return undefined
  try {
    const url = new URL(value)
    if (url.protocol !== 'https:' || url.username || url.password) return undefined
    return url.href
  } catch {
    return undefined
  }
}

const count = (value: unknown): number | undefined =>
  (typeof value === 'number' && Number.isFinite(value) && value >= 0 ? Math.floor(value) : undefined)

/** The feed's items, cleaned; anything malformed is left out. At most `limit`. */
export function parseFeed(raw: string, fetchedAt: number, limit = 40): PulseFeed | undefined {
  let data: unknown
  try {
    data = JSON.parse(raw)
  } catch {
    return undefined
  }
  if (!data || typeof data !== 'object') return undefined
  const d = data as Record<string, unknown>
  if (d.schema !== 1 || !Array.isArray(d.items)) return undefined
  const items: PulseItem[] = []
  for (const entry of d.items) {
    if (!entry || typeof entry !== 'object') continue
    const e = entry as Record<string, unknown>
    const title = clean(e.title, 100)
    const url = safeUrl(e.url)
    const source = clean(e.source, 28)
    if (!title || !url || !source) continue
    const text = clean(e.text, TEXT_MAX)
    const likes = count(e.likes)
    const points = count(e.points)
    const author = clean(e.author_name, 40)
    const story = clean(e.story, 200)
    const via = clean(e.via, 28)
    const discussion = safeUrl(e.discussion)
    items.push({ title, url, source, at: clean(e.published_at, 32) || undefined,
      ...(text && text !== title ? { text } : {}), ...(likes !== undefined ? { likes } : {}), ...(author ? { author } : {}),
      ...(story ? { story } : {}), ...(via ? { via } : {}), ...(points !== undefined ? { points } : {}),
      ...(discussion ? { discussion } : {}) })
    if (items.length >= limit) break
  }
  return { fetchedAt, generatedAt: clean(d.generated_at, 32) || undefined, items }
}

/** An X post leads with its author and age: `𝕏 @claudeai · 40m`, `· 3h`, `· 2d`. Other items: nothing. */
export function xLead(item: PulseItem, nowMs?: number): string {
  if (!item.source.startsWith('𝕏 @')) return ''
  const at = item.at ? Date.parse(item.at) : Number.NaN
  if (nowMs === undefined || !Number.isFinite(at)) return item.source
  const minutes = Math.max(1, Math.floor((nowMs - at) / 60_000))
  const age = minutes < 60 ? `${minutes}m` : minutes < 1440 ? `${Math.floor(minutes / 60)}h` : `${Math.floor(minutes / 1440)}d`
  return `${item.source} · ${age}`
}

/** The headline the spinner shows `elapsedMs` into a turn, cut to `room` columns, or nothing yet. */
export function tickerText(feed: PulseFeed | null | undefined, elapsedMs: number, room: number, nowMs?: number, beats = 1): string {
  if (!feed?.items.length || elapsedMs < PULSE_AFTER_MS || room < 24) return ''
  const at = beats > 0 ? Math.floor((elapsedMs - PULSE_AFTER_MS) / (PULSE_EVERY_MS * beats)) : 0
  const item = feed.items[at % feed.items.length]
  if (!item) return ''
  // A headline cut to a stub says nothing: drop the source before the title, and skip it if still too narrow.
  const lead = xLead(item, nowMs)
  if (lead && room - cells(lead) - 2 >= 24) return `${lead}: ${clean(item.title, room - cells(lead) - 2)}`
  if (lead) return clean(item.title, room)
  const tail = ` (${item.source})`
  if (room - cells(tail) >= 24) return `${clean(item.title, room - cells(tail))}${tail}`
  return clean(item.title, room)
}

/** An item's age: `40m`, `3h`, `2d`; nothing when the feed gave no time. */
export function ageOf(item: PulseItem, nowMs: number): string {
  const at = item.at ? Date.parse(item.at) : Number.NaN
  if (!Number.isFinite(at)) return ''
  const minutes = Math.max(1, Math.floor((nowMs - at) / 60_000))
  return minutes < 60 ? `${minutes}m` : minutes < 1440 ? `${Math.floor(minutes / 60)}h` : `${Math.floor(minutes / 1440)}d`
}

/** `1.2k` likes and the like: a count a glance can take in. */
export function countOf(n: number): string {
  if (n < 1000) return String(n)
  if (n < 10_000) return `${(n / 1000).toFixed(1).replace(/\.0$/, '')}k`
  return n < 1_000_000 ? `${Math.round(n / 1000)}k` : `${(n / 1_000_000).toFixed(1).replace(/\.0$/, '')}M`
}

/**
 * Pulse's row under the prompt: who, how long ago, the headline, and a dim
 * pointer to the reader when there is room. Each part is plain text: the
 * headline is drawn as a link by the caller. Nothing when too narrow.
 */
export function pulseRow(item: PulseItem | undefined, room: number, nowMs: number):
  { lead: string; title: string; tail: string } | undefined {
  if (!item || room < 30) return undefined
  const age = ageOf(item, nowMs)
  const lead = `${item.source}${age ? ` · ${age}` : ''}`
  const tailText = ' · /g-line news'
  const tail = room - cells(lead) - 2 - cells(tailText) >= 40 ? tailText : ''
  const titleRoom = room - cells(lead) - 2 - cells(tail)
  if (titleRoom < 24) return { lead: '', title: clean(item.title, room), tail: '' }
  return { lead, title: clean(item.title, titleRoom), tail }
}

/** The items the reader shows around the selected one: `[start, end)`, at most `size`. */
export function pageOf(count: number, selected: number, size = READER_PAGE): [number, number] {
  if (count <= size) return [0, count]
  const start = Math.min(Math.max(0, selected - Math.floor(size / 2)), count - size)
  return [start, start + size]
}

